// Returns USD-denominated 1e18 mantissas. At most one of liquidity/shortfall is non-zero.
// Isolated Pools: computed with the market LIQUIDATION THRESHOLD.
// Core Pool: CF == LT, so this is also the borrow-capacity number.
function getAccountLiquidity(address account)
    external view returns (uint256 error, uint256 liquidity, uint256 shortfall);

// Isolated Pools only. Computed with the market COLLATERAL FACTOR.
// This answers "how much more can I borrow", NOT "am I liquidatable".
function getBorrowingPower(address account)
    external view returns (uint256 error, uint256 liquidity, uint256 shortfall);

// Pre-flight simulator: effect of redeeming redeemTokens or borrowing borrowAmount
// in market vTokenModify. Use this to size a defensive repay before broadcasting.
function getHypotheticalAccountLiquidity(
    address account,
    address vTokenModify,
    uint256 redeemTokens,
    uint256 borrowAmount
) external view returns (uint256 error, uint256 liquidity, uint256 shortfall);

// Repay your own debt. Pulls `repayAmount` underlying from msg.sender.
function repayBorrow(uint repayAmount) external returns (uint);

// THIRD-PARTY REPAY. Pulls underlying from msg.sender (the payer),
// credits it against `borrower`'s debt. Borrower approves NOTHING.
// Payer must first call underlying.approve(vToken, repayAmount).
function repayBorrowBehalf(address borrower, uint repayAmount) external returns (uint);

// Liquidation: repay borrower's debt in this market, seize vTokenCollateral.
function liquidateBorrow(
    address borrower,
    uint repayAmount,
    VTokenInterface vTokenCollateral
) external returns (uint);

// Supply on behalf of another address: vTokens are credited to `receiver`.
function mintBehalf(address receiver, uint mintAmount) external returns (uint);

function mint(uint mintAmount) external returns (uint);
function redeemUnderlying(uint redeemAmount) external returns (uint);

// NON-VIEW: accrues interest first. Use eth_call (staticcall will revert).
// This is the number you want for an accurate health factor.
function borrowBalanceCurrent(address account) external virtual returns (uint);

// VIEW but STALE: does not accrue interest since last accrual block.
// Underestimates debt. Acceptable only for coarse screening.
function borrowBalanceStored(address account) public view virtual returns (uint);

function exchangeRateStored() public view virtual returns (uint);

// Returns (error, vTokenBalance, borrowBalance, exchangeRateMantissa).
// One call per market — the efficient primitive for building a health factor.
function getAccountSnapshot(address account)
    external view virtual returns (uint, uint, uint, uint);

